const source = $('Internal Storage - Prepare keys').item.json;
const rag = $('RAG - Search context').item.json || {};
const pageCount = Number(source.metadata?.page_count || 0);
const MAX_ANALYSIS_CHARS = 24000;
const warnings = Array.isArray(source.warnings) ? [...source.warnings] : [];
const excerpt = (value, limit) => value.length <= limit ? value : value.slice(0, Math.floor(limit * 0.7)) + '\n\n[trecho intermediário omitido por limite de contexto]\n\n' + value.slice(-Math.floor(limit * 0.3));
const chunks = Array.isArray(rag.chunks) ? rag.chunks : [];
let analysisMarkdown = String(source.markdown || '');
let analysisScope = { type: 'full_document', page_count: pageCount, retrieval: 'hybrid_current_document' };
if (chunks.length) {
  const context = chunks.map((chunk) => '## Página ' + chunk.page_start + '\n' + chunk.content).join('\n\n');
  analysisMarkdown = excerpt(context, MAX_ANALYSIS_CHARS);
  analysisScope = { type: 'hybrid_rag_current_document', page_count: pageCount, pages: [...new Set(chunks.flatMap((chunk) => [chunk.page_start, chunk.page_end]))].sort((a, b) => a - b), chunks: chunks.map((chunk) => ({ chunk_id: chunk.chunk_id, page_start: chunk.page_start, score: chunk.combined_score })), max_chars: MAX_ANALYSIS_CHARS };
} else {
  warnings.push('RAG não retornou contexto; o relatório seguirá com limitação explícita');
  if (analysisMarkdown.length > MAX_ANALYSIS_CHARS) { analysisMarkdown = excerpt(analysisMarkdown, MAX_ANALYSIS_CHARS); analysisScope = { type: 'full_document_excerpt', page_count: pageCount, max_chars: MAX_ANALYSIS_CHARS }; }
}
warnings.push('As citações devem ser copiadas literalmente do contexto recuperado e informar a página');
const expertInstructions = [
  'Você é um analista regulatório sênior. Produza um relatório técnico automatizado, claro e objetivo para operação, compliance e acompanhamento comercial.',
  'Retorne somente JSON válido conforme o contrato estrutural v2. Não escreva texto fora do JSON.',
  'Use exclusivamente o RAG_CONTEXT deste documento. Não use conhecimento externo, não invente dados e não misture documentos.',
  'Separe fatos documentados de interpretação técnica. Todo fundamento e apontamento deve conter paginas_origem e evidencia literal curta.',
  'Preserve deferido, indeferido, cancelado e outro. Não classifique dispositivo como medicamento ou suplemento.',
  'Gere parecer_tecnico com conclusão técnica, classificação geral, nível de risco prudente, fundamentos, apontamentos técnicos e recomendações ligadas por base_ids.',
  'Não declare autoridade regulatória, conformidade legal absoluta ou decisão definitiva. Se houver lacuna, contradição, contexto truncado ou risco relevante, descreva a limitação e as alternativas documentadas.',
  'Não solicite nem exija revisão humana. Retorne revisao_humana.necessaria=false; quando for útil, registre conferência opcional em avisos ou limites.',
  'Não invente páginas, prazos, responsáveis, normas ou consequências jurídicas. Falhas técnicas devem permanecer como erro do workflow.',
  'Limite a resposta a 12 itens por categoria, 6 fundamentos, 8 apontamentos e 6 recomendações; registre excesso em avisos.'
].join('\n');
const aiPrompt = expertInstructions + '\n\nDOCUMENTO/PROTOCOLO:\n' + source.submission_id + '\n\nRAG_CONTEXT:\n' + analysisMarkdown;
return [{ json: { ...source, analysis_markdown: analysisMarkdown, analysis_scope: analysisScope, retrieval_chunks: chunks, warnings, ai_prompt: aiPrompt, prompt_version: 'regulatory-extraction-v3' } }];
